"use client"

import * as React from "react"
import { Slider as SliderPrimitive } from "@base-ui/react/slider"

import { cn } from "@/lib/utils"

// Ledger Light Slider — recessed muted track, primary-blue range fill, and a
// thumb that reuses the primary Button's material (rim + soft blue glow).

const Slider = React.forwardRef<HTMLDivElement, SliderPrimitive.Root.Props>(
  ({ className, defaultValue, value, min = 0, max = 100, ...props }, ref) => {
    const _values = Array.isArray(value)
      ? value
      : Array.isArray(defaultValue)
        ? defaultValue
        : [min, max]

    return (
      <SliderPrimitive.Root
        data-slot="slider"
        ref={ref}
        thumbAlignment="edge"
        defaultValue={defaultValue}
        value={value}
        min={min}
        max={max}
        className={cn("relative w-full", className)}
        {...props}
      >
        <SliderPrimitive.Control className="flex w-full touch-none select-none items-center">
          <SliderPrimitive.Track data-slot="slider-track" className="relative h-2 w-full grow rounded-full bg-muted shadow-[var(--shadow-inset)]">
            <SliderPrimitive.Indicator data-slot="slider-range" className="absolute h-full rounded-full bg-primary" />
          </SliderPrimitive.Track>
          {Array.from({ length: _values.length }, (_, index) => (
            <SliderPrimitive.Thumb data-slot="slider-thumb" key={index} className="block h-5 w-5 rounded-full bg-primary border border-[var(--primary-rim)] shadow-[var(--shadow-primary-control)] transition-all duration-fast ease-out focus-visible:outline-none focus-visible:ring-[0.1875rem] focus-visible:ring-ring/30 data-disabled:pointer-events-none data-disabled:opacity-50 hover:shadow-[var(--shadow-primary-hover)]" />
          ))}
        </SliderPrimitive.Control>
      </SliderPrimitive.Root>
    )
  }
)
Slider.displayName = "Slider"

export { Slider }
